    {
      "name": "AddMonoidAlgebra.mul_apply_antidiagonal",
      "module_name": "Mathlib.Algebra.MonoidAlgebra.Defs",
      "kind": "theorem",
      "type": "∀ {M : Type u_2} {R : Type u_6} [inst : Semiring R] [inst_1 : Add M] (x y : AddMonoidAlgebra R M) (m : M)\n  (s : Finset (M × M)), (∀ {p : M × M}, p ∈ s ↔ p.1 + p.2 = m) → (x * y) m = ∑ p ∈ s, x p.1 * y p.2"
    },
    {
      "name": "AddMonoidAlgebra.mul_apply",
      "module_name": "Mathlib.Algebra.MonoidAlgebra.Defs",
      "kind": "theorem",
      "type": "∀ {M : Type u_2} {R : Type u_6} [inst : Semiring R] [inst_1 : Add M] [inst_2 : DecidableEq M]\n  (x y : AddMonoidAlgebra R M) (m : M),\n  (x * y) m = Finsupp.sum x fun m₁ r₁ => Finsupp.sum y fun m₂ r₂ => if m₁ + m₂ = m then r₁ * r₂ else 0"
    },
    {
      "name": "AddMonoidAlgebra.mul_apply_left",
      "module_name": "Mathlib.Algebra.MonoidAlgebra.Defs",
      "kind": "theorem",
      "type": "∀ {G : Type u_1} {R : Type u_6} [inst : Semiring R] [inst_1 : AddGroup G] (x y : AddMonoidAlgebra R G) (g : G),\n  (x * y) g = Finsupp.sum x fun h r => r * y (-h + g)"
    },
    {
      "name": "MonoidAlgebra.ring",
      "module_name": "Mathlib.Algebra.MonoidAlgebra.Defs",
      "kind": "instance",
      "type": "{M : Type u_2} → {R : Type u_6} → [inst : Ring R] → [Monoid M] → Ring (MonoidAlgebra R M)"
    },
    {
      "name": "WithLp.instUnitizationNormedAlgebra",
      "module_name": "Mathlib.Analysis.Normed.Algebra.UnitizationL1",
      "kind": "instance",
      "type": "{𝕜 : Type u_1} →\n  {A : Type u_2} →\n    [inst : NormedField 𝕜] →\n      [inst_1 : NonUnitalNormedRing A] →\n        [inst_2 : NormedSpace 𝕜 A] →\n          [inst_3 : IsScalarTower 𝕜 A A] → [inst_4 : SMulCommClass 𝕜 A A] → NormedAlgebra 𝕜 (WithLp 1 (Unitization 𝕜 A))"
    },
    {
      "name": "MonoidAlgebra.nonUnitalCommSemiring",
      "module_name": "Mathlib.Algebra.MonoidAlgebra.Defs",
      "kind": "instance",
      "type": "{M : Type u_2} →\n  {R : Type u_6} → [inst : CommSemiring R] → [CommSemigroup M] → NonUnitalCommSemiring (MonoidAlgebra R M)"
    },
    {
      "name": "MonoidAlgebra.nonUnitalCommRing",
      "module_name": "Mathlib.Algebra.MonoidAlgebra.Defs",
      "kind": "instance",
      "type": "{M : Type u_2} → {R : Type u_6} → [inst : CommRing R] → [CommSemigroup M] → NonUnitalCommRing (MonoidAlgebra R M)"
    },
